import * as m from './scripts/text/duration.ts';

const ok = [['1h30m15s', 5415], ['45s', 45], ['2m', 120], ['1h', 3600], ['1h5s', 3605]];
for (const [input, want] of ok) { const got = m.parseDuration(input); if (got !== want) { console.error(JSON.stringify({ input, got, want })); process.exit(1); } }
for (const input of ['', 'abc', '1s1h', '1h1h', '5', 'h']) {
  try { m.parseDuration(input); console.error('no error for ' + JSON.stringify(input)); process.exit(1); }
  catch (error) { if (!(error instanceof RangeError)) { console.error('not a RangeError for ' + JSON.stringify(input)); process.exit(1); } }
}
